sys_script_include.script:
var CiscoSecureAccessIntegrationAjax = Class.create();
CiscoSecureAccessIntegrationAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    createIntegration: function() {
        try {
            // params from client ID
            var username = this.getParameter('sysparm_username') || '';
            var password = this.getParameter('sysparm_password') || '';
            var webhook = this.getParameter('sysparm_webhook') || '';

            if (!username || !password || !webhook) {
                return JSON.stringify({
                    success: false,
                    message: 'Missing parameters. username, password and webhook are required.'
                });
            }

            // 1) Get latest access token from table u_cisco_secure_access_token
            var tokenGR = new GlideRecord('u_cisco_secure_access_token');
            tokenGR.orderByDesc('sys_created_on');
            tokenGR.setLimit(1);
            tokenGR.query();
            if (!tokenGR.next()) {
                return JSON.stringify({
                    success: false,
                    message: 'No access token record found in u_cisco_secure_access_token.'
                });
            }
            var accessToken = tokenGR.getValue('u_access_token');
            if (!accessToken) {
                return JSON.stringify({
                    success: false,
                    message: 'Access token is empty.'
                });
            }

            // 2) Call Cisco integrations API to create integration

            var integrationPayload = {
                type: "webhook.v1",
                name: "SNOW Alert",
                webhookConfig: { url: webhook }
            };

            var rm = new sn_ws.RESTMessageV2();
            rm.setHttpMethod('POST');
            rm.setEndpoint('https://api.sse.cisco.com/admin/v2/integrations');
            rm.setRequestHeader('Content-Type', 'application/json');
            rm.setRequestHeader('Authorization', 'Bearer ' + accessToken);
            rm.setRequestBody(JSON.stringify(integrationPayload));

            var response = rm.execute();
            var status = response.getStatusCode();
            var body = response.getBody();
            // attempt to parse the response
            var parsed;
            try { parsed = JSON.parse(body); } catch (e) { parsed = null; }

            if (status < 200 || status >= 300) {
                return JSON.stringify({
                    success: false,
                    message: 'Integration API failed with status ' + status,
                    status: status,
                    body: body
                });
            }

            // extract href from integration response
            var href = parsed && parsed.href ? parsed.href : null;
            if (!href) {
                return JSON.stringify({
                    success: false,
                    message: 'No href returned from integration API.',
                    body: body
                });
            }

            // 3) Call credentials endpoint
            // Ensure href doesn't duplicate base path. If href is absolute, use it, otherwise prefix with base.
            var credentialsEndpoint = href.indexOf('http') === 0 ? href + '/credentials' : 'https://api.sse.cisco.com/admin/v2' + href + '/credentials';

            var credentialsPayload = {
                name: "Add credentials to webhook",
                tags: ["string"],
                type: "basic-auth",
                value: { username: username, password: password }
            };

            var rm2 = new sn_ws.RESTMessageV2();
            rm2.setHttpMethod('POST');
            rm2.setEndpoint(credentialsEndpoint);
            rm2.setRequestHeader('Content-Type', 'application/json');
            rm2.setRequestHeader('Authorization', 'Bearer ' + accessToken);
            rm2.setRequestBody(JSON.stringify(credentialsPayload));

            var resp2 = rm2.execute();
            var status2 = resp2.getStatusCode();
            var body2 = resp2.getBody();
            var parsed2;
            try { parsed2 = JSON.parse(body2); } catch (e) { parsed2 = null; }

            if (status2 < 200 || status2 >= 300) {
                return JSON.stringify({
                    success: false,
                    message: 'Credentials API failed with status ' + status2,
                    status: status2,
                    body: body2
                });
            }

            // Successful result
            return JSON.stringify({
                success: true,
                message: 'Credentials added successfully',
                integrationResponse: parsed || body,
                credentialsResponse: parsed2 || body2,
                webhook: webhook
            });

        } catch (ex) {
            gs.error('CiscoIntegrationAjax.createIntegration error: ' + ex.message);
            return JSON.stringify({
                success: false,
                message: 'Server error: ' + ex.message
            });
        }
    }

});
